-- Queryopsy case database: Dark Store Delivery Audit
-- Source: data/samples/quickcommerce_placeholder.csv (PLACEHOLDER - synthetic)
-- Generated by pipeline/build.py - do not edit by hand.

-- One row per delivered quick-commerce order.
CREATE TABLE orders (
  order_id INTEGER PRIMARY KEY,
  platform TEXT REFERENCES platforms(platform),
  city TEXT,
  order_value REAL,
  delivery_min REAL,
  distance_km REAL,
  items INTEGER,
  category TEXT,
  payment TEXT,
  customer_rating REAL,
  discount INTEGER,
  partner_rating REAL
);

-- Delivery promise per platform (case configuration).
CREATE TABLE platforms (
  platform TEXT PRIMARY KEY,
  promised_min INTEGER
);

-- Per-order incentive paid to delivery partners.
CREATE TABLE rider_payouts (
  payout_id INTEGER PRIMARY KEY,
  order_id INTEGER REFERENCES orders(order_id),
  amount REAL
);

